yaml:
doz: space/3.1
space: t
owner: ada
brief: { text: Fix the failing build, refs: [README.md, "https://example.com/issue/1"] }
about: { title: Work on a project, summary: A manager and a helper., description: "Longer **Markdown**.", icon: wrench, tags: [web, build], category: Development, needs: { tools: [git] } }
layout: { view: iso, at: { helper: [2, 3] } }
network: { preset: locked, allow: [api.github.com] }
folders:
  repo: { external: ~/work/app, main: true }
  notes: {}
sandboxes:
  build: { image: claude-code }
agents:
  helper: { kind: claude-code, role: worker, folder: repo, restart: on-failure, network: standard }
  builder: { kind: claude-code, where: "sandbox:build", restart: "no" }
  old: { external: { sandbox: old-review }, role: reviewer }

doz: space/3.1
space: t
owner: ada
x-dozable: { brief: { text: Fix it }, about: { title: App }, network: standard, layout: { view: iso } }
folders:
  repo: { external: ~/work/app, x-dozable: { main: true } }
agents:
  h: { kind: claude-code, x-dozable: { restart: on-failure, network: standard } }
  old: { x-dozable: { external: { sandbox: old-review } } }
agent_defaults: { x-dozable: { isolation: vm } }

doz: space/3
space: t
owner: ada
